 public void Configure(Settings settings,string display){preferences=settings;level=Math.Max(1,Math.Min(4,settings.PerformanceLevel));var screen=WindowPlacement.MonitorBounds(display);if(!screen.HasValue){Hide();return;}float dpi=1;using(var scope=new WindowPlacement.PhysicalScope()){var s=Screen.AllScreens.FirstOrDefault(x=>x.DeviceName==display);if(s!=null){IntPtr handle=NativeMonitor(s.Bounds.Left+1,s.Bounds.Top+1);uint x,y;if(handle!=IntPtr.Zero&&GetDpiForMonitor(handle,0,out x,out y)==0)dpi=x/96f;}}scale=Math.Max(.75f,Math.Min(4,dpi*settings.PerformanceScale/100f));int logicalWidth=level==1?190:level==2?330:410,logicalHeight=level==1?76:level==2?168:level==3?298:438;scale=FitScale(scale,logicalWidth,logicalHeight,screen.Value.Width,screen.Value.Height);int w=(int)(logicalWidth*scale),h=(int)(logicalHeight*scale);var bounds=Placement(screen.Value,settings.PerformanceCorner,w,h,(int)(16*scale));using(var scope=new WindowPlacement.PhysicalScope()){Bounds=bounds;}Opacity=Math.Max(.3,Math.Min(1,settings.PerformanceOpacity/100.0));if(!Visible)Show();EnsureTransparency();Invalidate();}
