if((mask&128)!=0){Line(g,"RAM   "+Gib(Hardware.RamUsed)+" / "+Gib(Hardware.RamTotal),y,12,false,Theme.Text);y+=23;Line(g,"VRAM   "+(gpu!=null?Gib(gpu.Used)+" / "+Gib(gpu.Total):"Unavailable"),y,12,false,Theme.Text);y+=23;}if((mask&256)!=0&&Hardware.Cores.Length>0){int count=Hardware.Cores.Length;float width=(Width/scale-28)/count;for(int i=0;i<count;i++){using(var b=new SolidBrush(Theme.Accent))g.FillRectangle(b,(14+i*width)*scale,(y+22-Hardware.Cores[i]*.22f)*scale,Math.Max(1,(width-2)*scale),Math.Max(1,Hardware.Cores[i]*.22f*scale));}Line(g,"Per-core CPU activity",y+25,10,false,Theme.Muted);}}
